using System;
using System.Collections.Generic;
using System.Linq;
namespace MaritimeLegend.Domain {
public partial class GameService : IMarketService,IProductionService {
        public string License(){var city=S.cities[S.city];if(city.license)return "此城产业园已经开放";int foreign=S.cities.Count(x=>x.license)-1,cost=(int)((C.balance.upgrades.licenseBasePrice+foreign*C.balance.upgrades.licensePricePerCity)*(HasPartner(C.balance.partnerRoles.diplomat)?C.balance.upgrades.diplomatLicenseFactor:1)),rep=Math.Min(C.balance.upgrades.licenseMaxReputation,foreign*C.balance.upgrades.licenseReputationPerCity);if(city.reputation<rep)return "本城声望需要 "+rep+"，可通过市场真实交易获得";if(S.gold<cost)return "金币不足，需要 "+cost;S.gold-=cost;city.license=true;Emit("license");CheckQuest();return "产业许可证已签发";}
        public string Depart(int destination){if(S.atSea)return "已经在航行中";if(destination<0||destination>=C.ports.Length)return "无效目的港";if(destination==S.city)return "目的港不能与当前港相同";if(S.ships[0].hull<C.balance.navigation.minimumDepartureHull||S.ships[0].food<C.balance.navigation.minimumDepartureFood)return "请先修理船只并补给";S.sailing.manualMapId="";S.seaFrom=S.city;S.seaTo=destination;S.seaX=C.ports[S.city].x;S.seaY=C.ports[S.city].y;S.heading=Math.Atan2(C.ports[destination].y-S.seaY,C.ports[destination].x-S.seaX);SetSeaRegion(C.sailingDefaults.portRegions[S.city]);SetSailingMode("normal");S.atSea=true;S.screen="航海";return "解缆出航；鼠标指定航向，A/D调帆，R重置帆位，靠近目的港后入港";}
        public double Sail(double dt,double throttle){GameCalendar.ValidateSeconds(dt);if(!NormalSailing||DialogueOpen)return 0;throttle=Clamp(throttle,0,1);double oldX=S.seaX,oldY=S.seaY;var navigation=C.balance.navigation;
            int skill=C.balance.skills.navigationSkill;
            double baseSailSpeed=SkillResolver.Linear(S.skillLevels[skill],C.skills[skill].maxLevel,navigation.minSailSpeed,navigation.maxSailSpeed);
            double sailOpening=throttle*4;
            double speed=navigation.windSpeed*sailOpening*baseSailSpeed;
            S.seaX=Clamp(S.seaX+Math.Cos(S.heading)*speed*dt,S.sailing.manualMapId=="indian_ocean"?.001:C.balance.navigation.mapMinX,S.sailing.manualMapId=="indian_ocean"?.999:C.balance.navigation.mapMaxX);S.seaY=Clamp(S.seaY+Math.Sin(S.heading)*speed*dt,S.sailing.manualMapId=="indian_ocean"?.001:C.balance.navigation.mapMinY,S.sailing.manualMapId=="indian_ocean"?.999:C.balance.navigation.mapMaxY);if(SeaNavigation!=null){SeaNavigation.ResolveMove(oldX,oldY,S.seaX,S.seaY,out double safeX,out double safeY);S.seaX=safeX;S.seaY=safeY;speed=dt>0?Math.Sqrt(Math.Pow(S.seaX-oldX,2)+Math.Pow(S.seaY-oldY,2))/dt:0;}S.sailing.speed=speed;S.sailing.lastDayDistance+=Math.Sqrt(Math.Pow(S.seaX-oldX,2)+Math.Pow(S.seaY-oldY,2));return speed;}
        public double DistanceToPort(){var p=C.ports[S.seaTo];return Math.Sqrt(Math.Pow(p.x-S.seaX,2)+Math.Pow(p.y-S.seaY,2));}
        public string Arrive(){if(!NormalSailing||DialogueOpen)return "当前无法入港";if(DistanceToPort()>C.balance.navigation.arrivalRadius)return "尚未进入目的港安全半径";string route=S.seaFrom+">"+S.seaTo;if(!S.routes.Contains(route)){S.routes.Add(route);Emit("route");Gain(C.balance.skills.navigationSkill,C.balance.navigation.routeExperience);}S.city=S.seaTo;SetSeaRegion(C.sailingDefaults.portRegions[S.city]);S.sailing.speed=0;S.atSea=false;S.screen="城市";if(!S.visited.Contains(S.city))S.visited.Add(S.city);if(!S.discovered.Contains(S.city))S.discovered.Add(S.city);foreach(var p in S.partners.Where(x=>x.active))Gain(Array.FindIndex(C.skills,x=>x.id==C.partners[p.id].skill1),C.balance.navigation.partnerArrivalExperience);CheckQuest();return "已抵达 "+C.ports[S.city].name;}
        public string Rescue(){if(PromptedEncounter!=null)ResolveSeaEncounter(PromptedEncounter.instanceId,false);SetSailingMode("normal");RestoreSailingSupplies();S.sailing.speed=0;S.finalVoyage=false;S.gold=Math.Max(0,S.gold-C.balance.navigation.rescueFee);S.atSea=false;S.city=S.seaFrom;S.screen="城市";S.ships[0].hull=Math.Max(C.balance.navigation.rescueHull,S.ships[0].hull);S.ships[0].food=C.balance.navigation.rescueFood;return "港口救援队已接回船只，最多扣除100金币；货物保留";}
}}
